import { useEffect, useState } from "react";
import axios from "axios";
import { Box, Button, Modal, Typography, Grid, Paper, Stack } from "@mui/material";
import { useDropzone } from "react-dropzone";

const ImageUpload = () => {
  const [images, setImages] = useState({ Slider: [], Gallery: [], Stored: [] });
  const [open, setOpen] = useState(false);
  const [GetGallery, setGetGallery] = useState([]);
  const [GetStored, setGetStored] = useState([]);
  const [GetSlider, setGetSlider] = useState([]);
  
  const handleDrop = (acceptedFiles, category) => {
    setImages((prev) => ({ ...prev, [category]: [...prev[category], ...acceptedFiles] }));
  };

  const handleUpload = async () => {
    const formData = new FormData();
    Object.keys(images).forEach((category) => {
      images[category].forEach((file) => formData.append(category, file));
    });
    try {
      const response = await axios.post("http://localhost:5000/upload", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      console.log("Upload success:", response.data);
      fetchImages();
    } catch (error) {
      console.error("Error uploading images:", error);
    }
  };

  const fetchImages = async () => {
    try {
      const response = await axios.get("http://localhost:5000/images");

      setGetGallery(response.data?.[0]?.allphoto || []);
      setGetStored(response.data?.[0]?.bigphoto || []);
      setGetSlider(response.data?.[0]?.slider || []);

    } catch (error) {
      console.error("Error fetching images:", error);
    }
  };

  useEffect(() => {
    fetchImages();
  }, []);

  const Dropzone = ({ category }) => {
    const { getRootProps, getInputProps } = useDropzone({
      onDrop: (acceptedFiles) => handleDrop(acceptedFiles, category),
      accept: "image/*",
    });
    return (
      <Paper
        {...getRootProps()}
        sx={{ p: 2, textAlign: "center", cursor: "pointer", border: "2px dashed gray", mb: 2 }}
      >
        <input {...getInputProps()} />
        <Typography variant="body1">Drag & drop or click to upload {category} images</Typography>
      </Paper>
    );
  };
  return (
    <Box sx={{ p: 3, maxWidth: "600px", margin: "auto" }}>
      <Typography variant="h4" gutterBottom>Image Upload</Typography>
      <Dropzone category="Slider" />
      <Dropzone category="Gallery" />
      <Dropzone category="Stored" />
      <Button variant="contained" color="primary" fullWidth sx={{ my: 2 }} onClick={handleUpload}>
        Upload Images
      </Button>
      <Button variant="outlined" fullWidth onClick={() => setOpen(true)}>
        Open Gallery
      </Button>
      {/* Gallery Modal */}
      <Modal open={open} onClose={() => setOpen(false)}>
      
        <Box sx={{ 
          scrollbarWidth: "thin", // Firefox: Makes the scrollbar thin
            "&::-webkit-scrollbar": {
              width: "8px", // Chrome: Thin scrollbar
            },
            "&::-webkit-scrollbar-thumb": {
              backgroundColor: "rgba(0, 0, 0, 0.3)", // Scrollbar color
              borderRadius: "4px",
            },
            "&::-webkit-scrollbar-thumb:hover": {
              backgroundColor: "rgba(0, 0, 0, 0.5)", // Darker on hover
            },
              p: 3, bgcolor: "white", maxWidth: "60%", mx: "auto", my: 5, borderRadius: 2, height :'83%', overflow: 'scroll' }}>
          <Typography variant="h5" gutterBottom>Gallery</Typography>
          <Typography>Slider photos</Typography>
          <Stack spacing={2}>
                {GetSlider?.map((img, index) => (
                    <img src={img.url} alt={img.filename} style={{ width: "200px", borderRadius: "8px" }} />
                ))}
              </Stack>
          <Typography>All photos</Typography>
          <Stack spacing={2}>
                {GetGallery?.map((img, index) => (
                    <img src={img.url} alt={img.filename} style={{ width: "200px", borderRadius: "8px" }} />
                ))}
              </Stack>
          <Typography>Gallery Photo</Typography>
          <Stack spacing={2}>
                {GetStored?.map((img, index) => (
                    <img src={img.url} alt={img.filename} style={{ width: "200px", borderRadius: "8px" }} />
                ))}
              </Stack>
        </Box>
      </Modal>
    </Box>
  );
};

export default ImageUpload;
